package provider

import (
	"context"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/hashicorp/terraform-plugin-sdk/v2/diag"
	"github.com/hashicorp/terraform-plugin-sdk/v2/helper/schema"
)

func resourceFileRead() *schema.Resource {
	return &schema.Resource{
		ReadContext: resourceFileReadFunc,
		Schema: map[string]*schema.Schema{
			"base_path": {
				Type:     schema.TypeString,
				Required: true,
			},
			"relative_path": {
				Type:     schema.TypeString,
				Required: true,
			},
			"content": {
				Type:     schema.TypeString,
				Computed: true,
			},
		},
	}
}

func resourceFileReadFunc(ctx context.Context, d *schema.ResourceData, meta interface{}) diag.Diagnostics {
	basePath := d.Get("base_path").(string)
	relativePath := d.Get("relative_path").(string)

	// Construct the full path - note: filepath.Join does NOT prevent traversal
	// when the relative component starts with ../
	fullPath := filepath.Join(basePath, relativePath)

	// Attempt to read the file
	content, err := ioutil.ReadFile(fullPath)
	if err != nil {
		return diag.FromErr(fmt.Errorf("failed to read file at %s: %w", fullPath, err))
	}

	d.SetId(fullPath)
	d.Set("content", string(content))
	return nil
}

// APIHandler exposes provider state via HTTP for remote state sharing
func APIHandler() http.Handler {
	mux := http.NewServeMux()

	mux.HandleFunc("/api/v1/read-file", func(w http.ResponseWriter, r *http.Request) {
		basePath := r.URL.Query().Get("base_path")
		relPath := r.URL.Query().Get("path")

		if basePath == "" || relPath == "" {
			http.Error(w, "missing parameters", http.StatusBadRequest)
			return
		}

		// Basic validation - check it doesn't start with /
		if strings.HasPrefix(relPath, "/") {
			http.Error(w, "absolute paths not allowed", http.StatusForbidden)
			return
		}

		// This is vulnerable: ../../../etc/passwd bypasses the check above
		fullPath := filepath.Join(basePath, relPath)

		// Verify the file exists and is readable
		info, err := os.Stat(fullPath)
		if err != nil || info.IsDir() {
			http.Error(w, "file not found", http.StatusNotFound)
			return
		}

		content, err := ioutil.ReadFile(fullPath)
		if err != nil {
			http.Error(w, "read error", http.StatusInternalServerError)
			return
		}

		w.Header().Set("Content-Type", "application/octet-stream")
		w.Write(content)
	})

	mux.HandleFunc("/api/v1/list-files", func(w http.ResponseWriter, r *http.Request) {
		dir := r.URL.Query().Get("dir")
		if dir == "" {
			http.Error(w, "missing dir parameter", http.StatusBadRequest)
			return
		}
		files, err := ioutil.ReadDir(dir)
		if err != nil {
			http.Error(w, "cannot list directory", http.StatusInternalServerError)
			return
		}
		for _, f := range files {
			fmt.Fprintf(w, "%s\n", f.Name())
		}
	})

	return mux
}

func main() {
	listenAddr := os.Getenv("PROVIDER_LISTEN_ADDR")
	if listenAddr == "" {
		listenAddr = ":8443"
	}
	fmt.Printf("Starting provider API on %s\n", listenAddr)
	http.ListenAndServe(listenAddr, APIHandler())
}
